alter table push_outbox add column if not exists claimed_at timestamptz;
alter table push_outbox add column if not exists delivered bigint[] not null default '{}';
create index if not exists push_outbox_unsent_idx on push_outbox(created_at) where sent_at is null;

create or replace function ow_push_claim(p_limit int)
returns setof push_outbox
language sql security definer set search_path = public as $$
  update push_outbox o
     set claimed_at = now(), tries = o.tries + 1
   where o.id in (select x.id from push_outbox x
                   where x.sent_at is null and x.tries < 5 and x.created_at > now() - interval '1 day'
                     and (x.claimed_at is null or x.claimed_at < now() - interval '2 minutes')
                   order by x.id limit greatest(1, least(coalesce(p_limit, 100), 500))
                   for update skip locked)
  returning o.*
$$;
revoke all on function ow_push_claim(int) from public, anon, authenticated;
grant execute on function ow_push_claim(int) to service_role;

-- ---------------------------------------------------------------------
-- 0153_sales_price_up_told.sql
-- ---------------------------------------------------------------------
-- 0153 Sales, third: a supplier's price up that puts a line under its sale.
--
-- When the Buyer takes a supplier's new price (in person, by phone, or from
-- the supplier app) the line's cost rises (payload.items[].price, the old
-- one kept as priceWas). If it rises above what the line sells at, the line
-- sells at a loss, and that is the Manager's call (decision-rights.md §3,
-- manager.html lineBelowCost): Decide shows it whether or not anyone tagged
-- it. But nothing told the Manager, and when they set the new price nothing
-- told the salesperson, who has to tell the customer. Order #0554 (the
-- cross-app test of 21 Oct 2026) waited that way in silence.
--
-- Every hand-off that waits on someone pushes that person, so a new trigger
-- on saved_quotes pushes:
--
--   price.waits    the Manager (price.approve), when a line comes to sell
--                  under its cost with no answer from them for its price
--   price.decided  the salesperson who took the order, when the Manager
--                  sets the price on such a line: "Tell them."
--
-- A line a salesperson priced and tagged (priceBy) is left to 0120's
-- saved_quotes_ow_push, which already pushes both; this one only reads the
-- untagged lines, so nobody hears twice. Nothing else changes: the gate
-- (ow_gate_reason) and invoicing read what they read before.
--
-- Applied by hand, after 0152. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select tgname from pg_trigger where tgname = 'saved_quotes_ow_price_up';
--   select kind, title, body from push_outbox where dedupe like 'under:%' or dedupe like 'upset:%' order by id desc limit 5;
--
-- ROLLBACK:
--   drop trigger if exists saved_quotes_ow_price_up on saved_quotes;
--   drop function if exists saved_quotes_ow_price_up();
--   drop function if exists ow_line_under_cost(uuid, jsonb, jsonb);
-- ---------------------------------------------------------------------

-- An untagged line selling under its cost with no fresh answer from the
-- Manager (manager.html lineWaitsPrice, its lineBelowCost half).
create or replace function ow_line_under_cost(p_shop_id uuid, it jsonb, p_presets jsonb)
returns boolean
language plpgsql stable as $$
declare
  cost numeric;
  now_price numeric;
  r jsonb;
begin
  if jsonb_typeof(it) <> 'object' then return false; end if;
  if coalesce(it ->> 'priceBy', '') <> '' and coalesce(it ->> 'priceBy', '') <> 'false' then return false; end if;
  cost := ow_num(it ->> 'price');
  if coalesce(cost, 0) <= 0 or coalesce(ow_num(it ->> 'qty'), 0) <= 0 then return false; end if;
  now_price := round(case when coalesce(ow_num(it ->> 'sellPrice'), 0) > 0 then ow_num(it ->> 'sellPrice')
                          else ow_line_sell_price(p_shop_id, it, p_presets) end);
  if coalesce(now_price, 0) <= 0 or now_price >= cost then return false; end if;
  r := it -> 'priceReview';
  if jsonb_typeof(r) = 'object' and ow_num(r ->> 'price') = now_price and ow_num(r ->> 'qty') = ow_num(it ->> 'qty') then return false; end if;
  return true;
end $$;

create or replace function saved_quotes_ow_price_up() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  p jsonb := coalesce(new.payload, '{}'::jsonb);
  o jsonb := case when tg_op = 'UPDATE' then coalesce(old.payload, '{}'::jsonb) else '{}'::jsonb end;
  client text := coalesce(nullif(btrim(coalesce(new.client_name, '')), ''), nullif(btrim(coalesce(p -> 'client' ->> 'name', '')), ''), 'an order');
  taker uuid := ow_uuid(p ->> 'takenBy');
  ref jsonb := jsonb_build_object('table', 'saved_quotes', 'id', new.id);
  presets jsonb;
  items jsonb := case when jsonb_typeof(p -> 'items') = 'array' then p -> 'items' else '[]'::jsonb end;
  olds jsonb := case when jsonb_typeof(o -> 'items') = 'array' then o -> 'items' else '[]'::jsonb end;
  it jsonb;
  was jsonb;
  i integer;
  first_line jsonb;
  waiting text := '';
  r jsonb;
begin
  if coalesce(new.voided, false) or coalesce(new.invoiced, false) or new.status = 'completed' then return null; end if;
  begin
    presets := coalesce((select a.presets from app_settings a where a.shop_id = new.shop_id), '{}'::jsonb);
    for i in 0 .. jsonb_array_length(items) - 1 loop
      it := items -> i;
      -- The same line before this write: by its id, else by its place.
      was := null;
      if coalesce(it ->> 'lineId', '') <> '' then
        select e into was from jsonb_array_elements(olds) e where e ->> 'lineId' = it ->> 'lineId' limit 1;
      elsif i < jsonb_array_length(olds) then
        was := olds -> i;
      end if;

      if ow_line_under_cost(new.shop_id, it, presets) then
        if first_line is null then first_line := it; end if;
        waiting := waiting || coalesce(it ->> 'lineId', i::text) || '@' || coalesce(it ->> 'price', '') || ';';
      elsif was is not null and ow_line_under_cost(new.shop_id, was, presets) and taker is not null then
        -- The Manager answered a line that sold under its cost.
        r := it -> 'priceReview';
        if jsonb_typeof(r) = 'object' and (r ->> 'state') = 'changed'
           and (was -> 'priceReview') is distinct from r then
          perform ow_push(new.shop_id, 'price.decided', 'The Manager set a new price',
            client || ' — ' || coalesce(it ->> 'productName', 'an item') || ' is now ' || ow_money(ow_num(r ->> 'price')) || ' each. Tell them.',
            taker, null, null, ref, 'upset:' || new.id || ':' || coalesce(it ->> 'lineId', i::text) || ':' || coalesce(r ->> 'at', ''));
        end if;
      end if;
    end loop;

    -- Lines under their cost wait for the Manager: told once for each set of them.
    if waiting <> '' then
      perform ow_push(new.shop_id, 'price.waits', 'A price went up past the sale',
        client || ' — ' || coalesce(first_line ->> 'productName', 'a line') || ' now costs '
          || ow_money(ow_num(first_line ->> 'price')) || ', more than it sells at. Set the price.',
        null, 'price.approve', null, ref, 'under:' || new.id || ':' || md5(waiting));
    end if;
  exception when others then
    raise notice 'push (price up): % (%)', sqlerrm, sqlstate;
  end;
  return null;
end $$;

drop trigger if exists saved_quotes_ow_price_up on saved_quotes;
create trigger saved_quotes_ow_price_up after insert or update on saved_quotes
  for each row execute function saved_quotes_ow_price_up();

-- ---------------------------------------------------------------------
-- 0158_manager_asks.sql
-- ---------------------------------------------------------------------
-- 0158 Manager: the three answers the Manager app gives that nobody heard.
--
-- docs/decision-rights.md: every hand-off that waits on someone pushes that
-- person. The Manager app already makes these three calls or writes; the
-- database did not answer them, so the person on the other end was never
-- told:
--
--   1. refuse_restock_buy(p_id): the Manager says no to a carton's shelf
--      part (the Buyer's ask, 0151: 'held', no held_by, for_line set). The
--      line is 'cancelled', the owner's log gets it (restock.hold, as
--      hold_restock_buy writes it), and the Buyer who asked is pushed
--      (carton.refused) -- buyer.html reads a cancelled ask as "<Manager>
--      said no to the carton". Letting it go stays hold_restock_buy(id,
--      false), which pushes restock.released (0136).
--   2. A delivery given to a driver: when an order's payload.assignedDeliveryId
--      changes to a staff member with a login, that login is pushed
--      (job.given), whoever gave it (the Manager's hand-over, or the Store
--      at Load). A packer is not pushed here: handing an order to a packer
--      sets pickingStatus 'awaiting_accept', and notify-worker already sends
--      "New order to prepare" for that. A trip's runner is 0150's
--      (trip.sent, trip.taken), not repeated here.
--   3. tell_customer_change(shop, customer, to, what): after the Manager
--      edits a customer, the salesperson who last sold to them is pushed
--      (customer.changed) with what changed. customer.edit or credit.set.
--      The edit itself is logged by manager.html and 0122's customers guard.
--
-- Applied by hand, after 0120 (ow_push), 0131 (ow_first_name), 0136
-- (hold_restock_buy) and 0151 (restock_buys.for_line). Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select proname from pg_proc where proname in ('refuse_restock_buy', 'tell_customer_change', 'saved_quotes_ow_push_job');
--   select tgname from pg_trigger where tgname = 'saved_quotes_ow_push_job';
--   select kind, title, body from push_outbox where kind in ('carton.refused', 'job.given', 'customer.changed') order by id desc limit 5;
--
-- ROLLBACK:
--   drop trigger if exists saved_quotes_ow_push_job on saved_quotes;
--   drop function if exists saved_quotes_ow_push_job();
--   drop function if exists refuse_restock_buy(uuid);
--   drop function if exists tell_customer_change(uuid, text, uuid, text);
-- ---------------------------------------------------------------------

-- 1. No to a carton's shelf part.
create or replace function refuse_restock_buy(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  r record;
  nm text;
  who text;
  oid text;
begin
  select * into r from restock_buys where id = p_id for update;
  if not found then raise exception 'That restock line is gone.' using errcode = 'P0002'; end if;
  if not has_task(r.shop_id, 'restock.hold') then
    raise exception 'Answering a carton is the Manager''s (restock.hold).' using errcode = '42501';
  end if;
  if r.status = 'cancelled' then
    return jsonb_build_object('ok', true, 'id', p_id, 'status', r.status, 'already', true);
  end if;
  if r.status <> 'held' or r.held_by is not null or coalesce(r.for_line, '') = '' then
    raise exception 'Only a carton the Buyer asked about is refused; this line is % already.', r.status using errcode = 'OWRST';
  end if;
  select coalesce(p.name, r.product_id) into nm from products p where p.shop_id = r.shop_id and p.id = r.product_id;
  update restock_buys set status = 'cancelled' where id = p_id;
  perform manager_log_decision(r.shop_id, 'restock.hold',
    'Said no to a carton''s shelf part: ' || r.qty || ' × ' || coalesce(nm, 'an item'),
    case when r.price is not null then r.price * r.qty end,
    jsonb_build_object('table', 'restock_buys', 'id', r.id, 'line', r.for_line),
    jsonb_build_object('status', r.status), jsonb_build_object('status', 'cancelled'));
  who := coalesce(ow_first_name(r.shop_id, auth.uid()), 'The Manager');
  oid := nullif(split_part(r.for_line, ':', 1), '');
  perform ow_push(r.shop_id, 'carton.refused', who || ' said no to the carton',
    coalesce(nm, 'The item') || ': buy only what the order needs. The ' || r.qty || ' for the shelf stay unbought.',
    r.created_by, case when r.created_by is null then 'buy.restock' end, null,
    jsonb_build_object('table', 'restock_buys', 'id', r.id, 'line', r.for_line, 'orderId', oid),
    'cartonno:' || r.id);
  return jsonb_build_object('ok', true, 'id', p_id, 'status', 'cancelled');
end $$;
revoke all on function refuse_restock_buy(uuid) from public, anon;
grant execute on function refuse_restock_buy(uuid) to authenticated;

-- 2. A delivery given to a driver.
create or replace function saved_quotes_ow_push_job() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  p jsonb := coalesce(new.payload, '{}'::jsonb);
  o jsonb := coalesce(old.payload, '{}'::jsonb);
  client text := coalesce(nullif(btrim(coalesce(new.client_name, '')), ''), nullif(btrim(coalesce(p -> 'client' ->> 'name', '')), ''), 'An order');
  drv text := nullif(btrim(coalesce(p ->> 'assignedDeliveryId', '')), '');
  to_user uuid;
  who text;
begin
  if coalesce(new.voided, false) then return null; end if;
  if drv is null or drv like '\_\_%' or drv is not distinct from nullif(btrim(coalesce(o ->> 'assignedDeliveryId', '')), '') then return null; end if;
  if new.status not in ('preparing', 'pending_delivery') then return null; end if;
  begin
    select s.user_id into to_user from staff s where s.shop_id = new.shop_id and s.id = drv;
    if to_user is null then return null; end if;
    who := coalesce(ow_first_name(new.shop_id, auth.uid()), 'The shop');
    perform ow_push(new.shop_id, 'job.given', 'A delivery for you',
      who || ' gives you ' || client || ' to deliver.',
      to_user, null, null, jsonb_build_object('table', 'saved_quotes', 'id', new.id),
      'jobgiven:' || new.id || ':' || drv || ':' || coalesce(p -> 'carrier' ->> 'at', ''));
  exception when others then
    raise notice 'push (job given): % (%)', sqlerrm, sqlstate;
  end;
  return null;
end $$;
drop trigger if exists saved_quotes_ow_push_job on saved_quotes;
create trigger saved_quotes_ow_push_job after update on saved_quotes
  for each row execute function saved_quotes_ow_push_job();

-- 3. The salesperson told what changed on their customer.
create or replace function tell_customer_change(p_shop_id uuid, p_customer_id text, p_to uuid, p_what text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  c customers;
  who text;
begin
  if auth.uid() is null or not is_shop_member(p_shop_id) then
    raise exception 'Sign in to this shop first.' using errcode = '42501';
  end if;
  if not (has_task(p_shop_id, 'customer.edit') or has_task(p_shop_id, 'credit.set')) then
    raise exception 'Telling Sales about a customer is the Manager''s (customer.edit, credit.set).' using errcode = '42501';
  end if;
  select * into c from customers where shop_id = p_shop_id and id = p_customer_id;
  if not found then raise exception 'That customer is gone.' using errcode = 'P0002'; end if;
  if p_to is null or not exists (select 1 from shop_members m where m.shop_id = p_shop_id and m.user_id = p_to) then
    raise exception 'Nobody in this shop to tell.' using errcode = '22023';
  end if;
  if nullif(btrim(coalesce(p_what, '')), '') is null then
    raise exception 'Say what changed.' using errcode = '22023';
  end if;
  who := coalesce(ow_first_name(p_shop_id, auth.uid()), 'The Manager');
  perform ow_push(p_shop_id, 'customer.changed', coalesce(nullif(btrim(coalesce(c.name, '')), ''), 'A customer') || ' changed',
    who || ': ' || left(btrim(p_what), 200),
    p_to, null, null, jsonb_build_object('table', 'customers', 'id', c.id),
    'custchg:' || c.id || ':' || p_to || ':' || md5(btrim(p_what)) || ':' || (extract(epoch from now()) / 60)::bigint);
  return jsonb_build_object('ok', true, 'to', p_to);
end $$;
revoke all on function tell_customer_change(uuid, text, uuid, text) from public, anon;
grant execute on function tell_customer_change(uuid, text, uuid, text) to authenticated;
commit;

-- =====================================================================
-- STEP 3  CHECK AFTERWARDS (read-only): every row says ok
-- =====================================================================
select m, case when ok then 'ok' else 'MISSING' end from (values
  ('0120 push_outbox.claimed_at, .delivered', exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'push_outbox' and column_name = 'claimed_at')
                                              and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'push_outbox' and column_name = 'delivered')),
  ('0120 ow_push_claim',                      to_regprocedure('ow_push_claim(integer)') is not null),
  ('0153 price up, told',                     exists (select 1 from pg_trigger where tgname = 'saved_quotes_ow_price_up')),
  ('0158 the Manager''s asks',                to_regprocedure('refuse_restock_buy(uuid)') is not null and to_regprocedure('tell_customer_change(uuid, text, uuid, text)') is not null
                                              and exists (select 1 from pg_trigger where tgname = 'saved_quotes_ow_push_job'))
) as t(m, ok);

-- Pushes waiting to go out (read-only). Many unsent rows with an error
-- naming ow_push_claim mean push-send could not claim them before this.
select count(*) filter (where sent_at is null and created_at > now() - interval '1 day') as unsent_last_day,
       count(*) filter (where sent_at is not null and created_at > now() - interval '1 day') as sent_last_day,
       max(created_at) filter (where sent_at is not null) as last_sent
  from push_outbox;
